import inspect
from decimal import Decimal
from pathlib import Path

from ledgerly.money import Money

MONEY = Money
DECIMAL = Decimal


def literal(node):
    try:
        return ast.literal_eval(node)
    except Exception:
        return None


def numeric(node):
    return isinstance(node, (ast.Constant, ast.UnaryOp)) and literal(node) is not None


def money_node(value, currency_node):
    cur = copy.deepcopy(currency_node) if currency_node is not None else ast.Constant('USD')
    return ast.Call(
        func=ast.Name(id='Money', ctx=ast.Load()),
        args=[ast.Constant(value=str(value)), cur],
        keywords=[],
    )


def decimal_node(value):
    return ast.Call(
        func=ast.Name(id='Decimal', ctx=ast.Load()),
        args=[ast.Constant(value=str(value))],
        keywords=[],
    )


def transform_money_sequence(node, index, currency_node):
    if isinstance(node, (ast.List, ast.Tuple)):
        for element in node.elts:
            if isinstance(element, ast.Tuple) and len(element.elts) > index:
                target = element.elts[index]
                value = literal(target)
                if value is not None and numeric(target):
                    element.elts[index] = money_node(value, currency_node)
    return node


class TestTransformer(ast.NodeTransformer):
    def __init__(self, funcs):
        self.funcs = funcs

    def _signature(self, call):
        if isinstance(call.func, ast.Name) and call.func.id in self.funcs:
            return self.funcs[call.func.id]
        return None

    def _param_nodes(self, call, fn):
        params = list(inspect.signature(fn).parameters.values())
        mapping = {}
        for i, arg in enumerate(call.args):
            if i < len(params):
                mapping[params[i].name] = arg
        for kw in call.keywords:
            if kw.arg:
                mapping[kw.arg] = kw.value
        return params, mapping

    def visit_Call(self, node):
        self.generic_visit(node)
        fn = self._signature(node)
        if fn is None:
            return node
        params, mapping = self._param_nodes(node, fn)
        currency_node = mapping.get('currency')
        source_currency_node = mapping.get('src', currency_node)
        for i, arg in enumerate(node.args):
            if i >= len(params):
                break
            param = params[i]
            ann = param.annotation
            if ann is MONEY:
                value = literal(arg)
                if value is not None and numeric(arg):
                    cur = source_currency_node if 'src' in mapping else currency_node
                    node.args[i] = money_node(value, cur)
            elif ann is DECIMAL:
                value = literal(arg)
                if value is not None and numeric(arg):
                    node.args[i] = decimal_node(value)
            elif param.name == 'amounts' and isinstance(arg, (ast.List, ast.Tuple)):
                if isinstance(arg, ast.List):
                    for j, element in enumerate(arg.elts):
                        value = literal(element)
                        if value is not None and numeric(element):
                            arg.elts[j] = money_node(value, currency_node)
            elif param.name == 'rows':
                transform_money_sequence(arg, 2, currency_node)
            elif param.name == 'lines':
                transform_money_sequence(arg, 1, currency_node)
        return node

    def visit_AssertEqual(self, node):
        self.generic_visit(node)
        self._wrap_expected(node, node.left, node.comparators[0])
        return node

    def visit_AssertNotEqual(self, node):
        self.generic_visit(node)
        self._wrap_expected(node, node.left, node.comparators[0])
        return node

    def _wrap_expected(self, node, left, right):
        fn = self._signature(left)
        if fn is None:
            return
        params, mapping = self._param_nodes(left, fn)
        ret = inspect.signature(fn).return_annotation
        currency_node = mapping.get('dst', mapping.get('currency'))
        if ret is MONEY:
            value = literal(right)
            if value is not None and numeric(right):
                node.comparators[0] = money_node(value, currency_node)
        elif ret is list and isinstance(right, ast.List):
            for j, element in enumerate(right.elts):
                value = literal(element)
                if value is not None and numeric(element):
                    right.elts[j] = money_node(value, currency_node)


for path in sorted(Path('tests').glob('test_*.py')):
