    for statement in tree.body:
        if isinstance(statement, ast.ImportFrom) and statement.module and statement.module.startswith('ledgerly.'):
            module = importlib.import_module(statement.module)
            for alias in statement.names:
                funcs[alias.asname or alias.name] = getattr(module, alias.name)
    tree = TestTransformer(funcs).visit(tree)
